{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Prucalopride, a structurally related substituted benzamide with a piperidine side chain, has an absolute oral bioavailability greater than 90% in humans, strongly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Metoclopramide shares the exact 4-amino-5-chloro-2-methoxybenzamide core with the query and has a mean oral bioavailability of 76% (range 64-97%) in normal volunteers, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Amisulpride, another substituted benzamide with a basic amine side chain, has an absolute bioavailability of about 50% in humans, supporting high oral bioavailability for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Melperone, a fluorophenyl piperidine derivative, has an absolute bioavailability of 64 ± 16.6% in healthy volunteers, supporting high bioavailability through the piperidine/fluorophenyl motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Lumateperone has a very low absolute bioavailability of 4.4%, but its low structural similarity and different scaffold limit transferability to the query; this is outweighed by the closer benzamide analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a substituted benzamide with a basic piperidine side chain, closely related to prucalopride and metoclopramide, both of which show high absolute oral bioavailability (76% to >90%). Other benzamide/piperidine analogues such as amisulpride and melperone also show F values of 50-67%. The only low-bioavailability analogue, lumateperone, is structurally distant and its poor F reflects scaffold-specific metabolism. Therefore, F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the exact query molecule.",
    "Morgan similarities to the closest analogues are moderate (0.36-0.38), so exact transferability is not perfect.",
    "Potential first-pass metabolism or efflux liabilities specific to the query's 4-fluorophenoxypropyl piperidine substituent were not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

